import { NextRequest } from 'next/server';
import { TABLE_REGISTRY } from '@/lib/tableRegistry';
import { dataGet, dataPost, dataPatch, dataDelete, dataNotFound } from '@/lib/dataRoute';

/* Erp domain data route (GENERATED by the wire closure, 2026-11-15):
   the named API surface for the erp tables that had no hand-written
   route. Tenant-scoped CRUD through the shared handler in
   lib/dataRoute.ts, driven by each table's TABLE_REGISTRY entry.
   Tables served here:
   - erp_audit_log
   - erp_document_sequences
   - erp_fulfillment_lines
   - erp_idempotency_keys
   - erp_inventory_balances
   - erp_inventory_cost_layers
   - erp_inventory_lots
   - erp_inventory_reservations
   - erp_inventory_serial_numbers
   - erp_inventory_transactions
   - erp_order_status_history
   - erp_package_items
   - erp_packages
   - erp_pick_task_lines
   - erp_pick_tasks
   - erp_pick_waves
   - erp_product_barcodes
   - erp_product_categories
   - erp_product_variants
   - erp_replenishment_recommendations
   - erp_shipment_packages
   - erp_uom_conversions
   - erp_vendor_items
   - erp_vendors
   - erp_warehouse_zones
*/

const SERVED = new Set([
  'erp_audit_log',
  'erp_document_sequences',
  'erp_fulfillment_lines',
  'erp_idempotency_keys',
  'erp_inventory_balances',
  'erp_inventory_cost_layers',
  'erp_inventory_lots',
  'erp_inventory_reservations',
  'erp_inventory_serial_numbers',
  'erp_inventory_transactions',
  'erp_order_status_history',
  'erp_package_items',
  'erp_packages',
  'erp_pick_task_lines',
  'erp_pick_tasks',
  'erp_pick_waves',
  'erp_product_barcodes',
  'erp_product_categories',
  'erp_product_variants',
  'erp_replenishment_recommendations',
  'erp_shipment_packages',
  'erp_uom_conversions',
  'erp_vendor_items',
  'erp_vendors',
  'erp_warehouse_zones'
]);

function entry(table: string) {
  return SERVED.has(table) ? TABLE_REGISTRY[table] ?? null : null;
}

export async function GET(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataGet(req, table, r) : dataNotFound(table);
}

export async function POST(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPost(req, table, r) : dataNotFound(table);
}

export async function PATCH(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPatch(req, table, r) : dataNotFound(table);
}

export async function DELETE(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataDelete(req, table, r) : dataNotFound(table);
}
